package java.lang.invoke;

/** Closed-world callable targets; generated bytecode implements the direct invocation body. */
public abstract class MethodHandle {
    private final MethodType type;
    protected MethodHandle(MethodType type){this.type=type;}
    public final MethodType type(){return type;}
    protected abstract Object javawInvoke(Object[] arguments) throws Throwable;
    public final Object invokeWithArguments(Object... arguments) throws Throwable {
        if(arguments==null)arguments=new Object[0];
        if(arguments.length!=type.parameterCount())throw new WrongMethodTypeException();
        Object[] converted=new Object[arguments.length];
        for(int i=0;i<converted.length;i++)converted[i]=convert(arguments[i],Object.class,type.parameterType(i));
        return javawInvoke(converted);
    }
    public final Object javawCall(MethodType callType,Object[] arguments,boolean exact) throws Throwable {
        if(exact){if(type!=callType)throw new WrongMethodTypeException();return javawInvoke(arguments);}
        return asType(callType).javawInvoke(arguments);
    }
    public final MethodHandle asType(MethodType desired){return type==desired?this:new Adapted(this,desired);}
    public final MethodHandle bindTo(Object value){
        if(type.parameterCount()==0 || type.parameterType(0).isPrimitive())throw new IllegalArgumentException();
        return new Bound(this,type.parameterType(0).cast(value));
    }
    public boolean isVarargsCollector(){return false;}
    public MethodHandle asFixedArity(){return this;}
    public String toString(){return "MethodHandle".concat(type.toString());}
    private static final class Bound extends MethodHandle {
        private final MethodHandle target;private final Object value;
        Bound(MethodHandle target,Object value){super(target.type().dropParameterTypes(0,1));this.target=target;this.value=value;}
        protected Object javawInvoke(Object[] arguments) throws Throwable {
            Object[] all=new Object[arguments.length+1];all[0]=value;System.arraycopy(arguments,0,all,1,arguments.length);
            return target.javawInvoke(all);
        }
    }
    private static final class Adapted extends MethodHandle {
        private final MethodHandle target;
        Adapted(MethodHandle target,MethodType desired){
            super(desired);this.target=target;
            if(desired.parameterCount()!=target.type().parameterCount())throw new WrongMethodTypeException();
            for(int i=0;i<desired.parameterCount();i++)if(!convertible(desired.parameterType(i),target.type().parameterType(i)))throw new WrongMethodTypeException();
            if(!convertible(target.type().returnType(),desired.returnType()))throw new WrongMethodTypeException();
        }
        protected Object javawInvoke(Object[] arguments) throws Throwable {
            Object[] converted=new Object[arguments.length];
            for(int i=0;i<converted.length;i++)converted[i]=convert(arguments[i],type().parameterType(i),target.type().parameterType(i));
            Object result=target.javawInvoke(converted);
            return convert(result,target.type().returnType(),type().returnType());
        }
    }
    private static Class<?> primitive(Class<?> type){
        if(type==Boolean.class)return boolean.class;if(type==Byte.class)return byte.class;if(type==Character.class)return char.class;
        if(type==Short.class)return short.class;if(type==Integer.class)return int.class;if(type==Long.class)return long.class;
        if(type==Float.class)return float.class;if(type==Double.class)return double.class;return null;
    }
    private static Class<?> wrapper(Class<?> type){
        if(type==boolean.class)return Boolean.class;if(type==byte.class)return Byte.class;if(type==char.class)return Character.class;
        if(type==short.class)return Short.class;if(type==int.class)return Integer.class;if(type==long.class)return Long.class;
        if(type==float.class)return Float.class;return Double.class;
    }
    private static boolean widens(Class<?> from,Class<?> to){
        if(from==to)return true;
        if(from==boolean.class || to==boolean.class || to==byte.class || to==char.class)return false;
        if(from==byte.class)return true;
        if(to==short.class)return false;
        if(from==short.class || from==char.class)return true;
        if(to==int.class)return false;if(from==int.class)return true;
        if(to==long.class)return false;if(from==long.class)return true;
        return from==float.class && to==double.class;
    }
    private static boolean convertible(Class<?> from,Class<?> to){
        if(from==void.class || to==void.class)return true;
        if(from.isPrimitive())return to.isPrimitive()?widens(from,to):to.isAssignableFrom(wrapper(from));
        if(!to.isPrimitive())return true;
        Class<?> unboxed=primitive(from);return unboxed==null?from.isAssignableFrom(wrapper(to)):widens(unboxed,to);
    }
    private static Object zero(Class<?> type){
        if(!type.isPrimitive() || type==void.class)return null;
        if(type==boolean.class)return Boolean.FALSE;if(type==byte.class)return Byte.valueOf((byte)0);
        if(type==char.class)return Character.valueOf((char)0);if(type==short.class)return Short.valueOf((short)0);
        if(type==int.class)return Integer.valueOf(0);if(type==long.class)return Long.valueOf(0);
        if(type==float.class)return Float.valueOf(0);return Double.valueOf(0);
    }
    public static Object javawConvert(Object value,Class<?> from,Class<?> to){return convert(value,from,to);}
    private static Object convert(Object value,Class<?> from,Class<?> to){
        if(to==void.class)return null;if(from==void.class)return zero(to);
        if(!to.isPrimitive())return to.cast(value);
        if(value==null)throw new NullPointerException();
        Class<?> actual=primitive(value.getClass());
        if(actual==null || !widens(actual,to))throw new ClassCastException();
        if(to==boolean.class || to==char.class || to==byte.class)return value;
        if(to==short.class)return Short.valueOf(((Number)value).shortValue());
        if(to==int.class)return Integer.valueOf(actual==char.class?((Character)value).charValue():((Number)value).intValue());
        if(to==long.class)return Long.valueOf(actual==char.class?((Character)value).charValue():((Number)value).longValue());
        if(to==float.class)return Float.valueOf(actual==char.class?((Character)value).charValue():((Number)value).floatValue());
        return Double.valueOf(actual==char.class?((Character)value).charValue():((Number)value).doubleValue());
    }
}
